// TH16 v1.00a Stage 1 mid-stage wave 5.
// Source: st01.ecl.txt MainSub04:1259-1268 + MainSub05:1270-1295,
// deps GirlA03:249-263, GirlBlueA03:488-495, GirlRedA03:985-992,
// GirlD01:665-689, GirlD01_at:691-753. Both entry subs start on the same frame
// (MainLatter:1067-1068: async MainSub05, then sync MainSub04).

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;
const TH16_RING_BALL2: int = 464;
const COLOR_13: int = 13;

// ---- training shell (control) -------------------------------------------

async sub pattern() {
    wait(OPENING_BUFFER);
    // MainLatter:1067 @MainSub05() async starts a separate call stack;
    // MainLatter:1068 @MainSub04() runs in this task.
    spawn redblue_waves();
    d01_waves();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---- source MainSub04: GirlD01 pairs ------------------------------------

sub d01_waves() {
    _ = spawn_enemy(100fx, -24fx, 600, 0, 1000, 0, girl_d01);
    _ = spawn_enemy(-100fx, -24fx, 600, 0, 1000, 0, girl_d01);
    wait(300);
    _ = spawn_enemy(128fx, -24fx, 600, 0, 1000, 0, girl_d01);
    _ = spawn_enemy(-128fx, -24fx, 600, 0, 1000, 0, girl_d01);
    wait(60);
}

// ---- source MainSub05: GirlRedA03 / GirlBlueA03 columns -----------------

async sub redblue_waves() {
    var ax: fx = -120fx;
    wait(180);
    for wave in 0..8 {
        // MainSub05_160: red leader at A-60, blue at A; A += 24 each round.
        _ = spawn_enemy(ax - 60fx, -32fx, 40, 0, 1000, 0, girl_a);
        _ = spawn_enemy(ax, -20fx, 40, 0, 1000, 0, girl_a);
        ax = ax + 24fx;
        wait(25);
    }
    wait(120);
    for rev in 0..8 {
        // MainSub05_544: mirrored pass, A -= 24 each round.
        _ = spawn_enemy(ax - 60fx, -32fx, 40, 0, 1000, 0, girl_a);
        _ = spawn_enemy(ax, -20fx, 40, 0, 1000, 0, girl_a);
        ax = ax - 24fx;
        wait(25);
    }
}

// ---- GirlA03 (both GirlRedA03 and GirlBlueA03 call it) ------------------

async sub girl_a() {
    set_invuln(65535);
    set_hurtbox(12fx);              // 500 setHurtbox(24,24)
    set_hitbox(8fx);                // 501 setHitbox(16,16)
    move_vel(0, 90deg, 1fx, EASE_LINEAR);             // 404 moveVel(pi/2, 1.0)
    wait(30);
    // 405 moveVelTime(60, 0, -999999, 2.8): angle sentinel keeps pi/2,
    // speed is the only interpolated axis (linear, mode 0).
    move_speed(60, 2.8fx, EASE_LINEAR);
    loop { wait(1000); }
}

// ---- GirlD01 main -------------------------------------------------------

async sub girl_d01() {
    set_invuln(65535);
    set_hurtbox(16fx);              // 500 setHurtbox(32,32)
    set_hitbox(12fx);               // 501 setHitbox(24,24)
    move_vel(0, 90deg, 3fx, EASE_LINEAR);             // 404 moveVel(pi/2, 3.0)
    move_speed(60, 0fx, EASE_QUAD_IN);                // 405 mode1: speed 3 -> 0
    spawn girl_d01_at();                              // 679 @GirlD01_at() async
    wait(80);
    move_speed(120, 0.5fx, EASE_QUAD_IN);             // 681 mode1: speed 0 -> 0.5
    wait(60);
    loop { wait(1000); }
}

// ---- GirlD01_at: aimed alternating-layer ring ---------------------------

async sub girl_d01_at() {
    wait(60);
    var n: int = 6;                 // 625 etCount: paths
    var m: int = 3;                 // 625 etCount: layers
    var s0: fx = 1.6fx;             // 605 etSpeed: first layer
    var s1: fx = 1.4fx;             // 605 etSpeed: last layer
    var interval: int = 120;        // 749 wait per burst
    var bursts: int = 1;            // 736 diffI($A, 1,1,3,4)
    var rank: int = global(GVAR_RANK);
    if rank == 1 { n = 10; m = 5; s0 = 1.6fx; s1 = 1.6fx; }
    if rank == 2 { n = 12; m = 7; s0 = 2.6fx; s1 = 1.9fx; interval = 60; bursts = 3; }
    if rank >= 3 { n = 14; m = 7; s0 = 2.6fx; s1 = 1.9fx; interval = 60; bursts = 4; }
    // 600-611 etNew/etAim(9)/etSprite(7,13)/etCount/etAngle/etSpeed.
    sh_reset(0);
    sh_sprite(0, TH16_RING_BALL2, COLOR_13);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, n, 1);
    var b: int = bursts;
    while b > 0 {
        fire_wave(m, s0, s1);
        b = b - 1;
        wait(interval);
    }
}

// 607 etAim(0,9) with 604 etAngle(0,0,delta=0.05235988rad=3deg=546 BAM):
//   angle = A + alpha + (-1)^q * (R(i) + H(M,q))
//   speed = s0 + (s1-s0)*k/(M-1), k = ((q + M%2)/2)*2
// M is 3/5/7 here (odd), so H = floor((q+1)/2)*delta.
// Each layer is a full n-way ring at base +-H, so one sh_fire per layer keeps the
// layer-outer order; the odd-layer mirror is the same ring up to 1 BAM rounding.
sub fire_wave(m: int, s0: fx, s1: fx) {
    for q in 0..m {
        var k: int = ((q + m%2)/2)*2;
        var sp: fx = s0;
        if m > 1 { sp = s0 + (s1-s0)*k/(m-1); }
        var h: int = ((q+1)/2)*546;
        var base: int = h;
        if q%2 != 0 { base = 0 - h; }
        sh_angle(0, base as angle, 0deg);
        sh_speed(0, sp, 0fx);
        // EX type 2 ANIM a=1: birth backstep position -= 4*velocity.
        sh_dist(0, 0fx - 4fx*sp);
        sh_fire(0);
    }
}
